#!/bin/sh
# Generated by `eval cloud-context` (SPEC §11.7): start the target's services, then run this task's version.
# Whatever happens, the task leaves a status.json: when it stops before writing its own, fallback-status.cjs writes one.
set -u
APP_DIR="${APP_DIR:-/app}"
RESULTS_DIR="${RESULTS_DIR:-/mnt/results}"
STARTED="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
cd "$APP_DIR"

fallback() {
  node image/fallback-status.cjs "$RESULTS_DIR" "$STARTED" "$1" "$2" {{serviceLogFiles}} || echo "fallback-status failed" >&2
}

if ! ( {{startServices}} ); then
  fallback 1 "The target's services did not start; see the task log"
  exit 1
fi

node_modules/.bin/tsx src/cli.ts eval cloud-task --results "$RESULTS_DIR" {{serviceLogs}} &
child=$!
# Pass Cloud Run's stop signal on to the task, then wait for it to finish.
trap 'kill -TERM "$child" 2>/dev/null' TERM INT
wait "$child"
code=$?
while kill -0 "$child" 2>/dev/null; do
  wait "$child"
  code=$?
done
if [ "$code" -ne 0 ]; then
  fallback "$code" "eval cloud-task stopped before writing status.json; see the task log"
fi
exit "$code"
